    const parts = [];
    const effort = EFFORT_LABELS[String(prompt.effortLevel)];
    if (effort !== undefined && effort !== "standard") {
        parts.push(`effort: ${effort}`);
    }
    if (prompt.model !== undefined && prompt.model !== "") {
        parts.push(`model: ${prompt.model}`);
    }
